package odc;
import java.util.*;
public final class ComputeEngineTest {
    static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static void eq(long a,long b,String m){check(a==b,m+" expected="+a+" got="+b);}
    public static void main(String[] args){ComputeEngine.Profile cpu=ComputeEngine.mining(1,0,0,20),gpu=ComputeEngine.mining(2,0,1,20),max=ComputeEngine.mining(2,0,4,20);eq(8,cpu.work,"CPU mining");eq(192,gpu.work,"CPU+GPU mining");eq(672,max.work,"4 GPUs");eq(105,gpu.fePerTick,"incremental power");eq(0,ComputeEngine.mining(1,1,4,20).work,"GPU limit");
        ComputeEngine.Plan p=ComputeEngine.plan(new ComputeEngine.Profile[]{max,max,max},new int[]{0,0,1},new int[]{3,100,100},new int[]{10,20},new int[]{100000,100000},100,0);eq(10,p.bandwidth[0]+p.bandwidth[1],"rack local limit");eq(max.mbps,p.bandwidth[2],"independent switch");check(p.bandwidth[0]<=3,"NIC cap");
        p=ComputeEngine.plan(new ComputeEngine.Profile[]{gpu,gpu},new int[]{0,1},new int[]{100,100},new int[]{0,100},new int[]{99999,99999},100,0);eq(0,p.bandwidth[0],"no borrowing switch");eq(gpu.mbps,p.bandwidth[1],"second works");
        p=ComputeEngine.plan(new ComputeEngine.Profile[]{cpu},new int[]{0},new int[]{100},new int[]{100},new int[]{0},100,0);eq(0,p.bandwidth[0],"no power");eq(0,p.energyCost[0],"no reward cost");
        Random random=new Random(20261124L);for(int iter=0;iter<20000;iter++){int n=1+random.nextInt(32),racks=1+random.nextInt(8),wan=random.nextInt(200);int[] owners=new int[n],port=new int[n],budget=new int[racks],sw=new int[racks],local=new int[racks],spent=new int[racks];ComputeEngine.Profile[] ps=new ComputeEngine.Profile[n];
            for(int i=0;i<racks;i++){budget[i]=random.nextInt(20001);sw[i]=random.nextInt(100);}
            for(int i=0;i<n;i++){int a=random.nextInt(5),b=random.nextInt(5-a);ps[i]=ComputeEngine.mining(1+random.nextInt(2),a,b,20);owners[i]=random.nextInt(racks);port[i]=random.nextInt(25);}
            ComputeEngine.Plan result=ComputeEngine.plan(ps,owners,port,sw,budget,wan,iter);int used=0,possible=0;for(int i=0;i<n;i++){int g=result.bandwidth[i],cap=result.local[i],energy=result.energyLimited[i];check(cap>=0&&cap<=port[i]&&cap<=ps[i].mbps,"physical port cap");check(g>=0&&g<=energy&&energy<=cap,"energy cap");eq(ps[i].energy(g),result.energyCost[i],"cost formula");if(g==0)eq(0,ps[i].reward(g),"no work reward");check(ps[i].reward(g)<=ps[i].microMilliPerSecond,"reward cap");used+=g;possible+=energy;local[owners[i]]+=cap;spent[owners[i]]+=result.energyCost[i];}
            eq(Math.min(wan,possible),used,"WAN cap");for(int i=0;i<racks;i++){check(local[i]<=sw[i],"local switch cap");check(spent[i]<=budget[i],"rack budget");}}
        Map<String,List<String>> g=new HashMap<>();g.put("PC",Arrays.asList("A","B"));g.put("A",Arrays.asList("PC","B","Rack"));g.put("B",Arrays.asList("PC","A"));g.put("Rack",Arrays.asList("A","Station"));g.put("Station",Arrays.asList("Rack"));eq(5,TopologySearch.component("PC",g::get,x->true,5).size(),"network loop dedup");check(TopologySearch.component("PC",g::get,x->true,4)==null,"overflow fails closed");eq(3,TopologySearch.component("PC",g::get,x->!x.equals("Rack"),5).size(),"disconnect");
        System.out.println("PASS: "+checks+" mining/energy/network assertions; 20000 random scenarios; topology loops/overflow.");}
}
